local function JH_mix(key, data)
    local S = {}
    for i = 0, 255 do S[i] = i end
    local j = 0
    for i = 0, 255 do
        j = (j + S[i] + string.byte(key, (i % #key) + 1)) % 256
        S[i], S[j] = S[j], S[i]
    end
    local ii, jj = 0, 0
    local out = {}
    for k = 1, #data do
        ii = (ii + 1) % 256
        jj = (jj + S[ii]) % 256
        S[ii], S[jj] = S[jj], S[ii]
        out[k] = B.bxor(data[k], S[(S[ii] + S[jj]) % 256])
    end
    return out
end
